```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()

        if re.fullmatch(r"\d{4,5}-\d{4}", value):
            value = value.split("-", 1)[0]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    normalized = []

    for index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Rows without either valid contact method cannot participate in matching.
        if not email and not phone:
            continue

        first_name = normalize_name(row["first_name"])
        last_name = normalize_name(row["last_name"])
        source = row["source"].strip().lower()
        updated = parse_updated(row["updated"])

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        normalized.append({
            "index": index,
            "first_name": first_name,
            "last_name": last_name,
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "tags": tags,
            "opted_out": row["opted_out"].strip().lower()
            in {"y", "yes", "true", "1"},
            "updated_dt": updated,
        })

    # Disjoint-set union tracks transitive matches.
    parent = list(range(len(normalized)))
    rank = [0] * len(normalized)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)

        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    email_owner = {}
    phone_last_owner = {}

    for i, row in enumerate(normalized):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = i
            else:
                union(i, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_owner.get(key)
            if previous is None:
                phone_last_owner[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, row in enumerate(normalized):
        groups.setdefault(find(i), []).append(row)

    def pick(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return best[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["index"] for row in group),
    )

    result = []
    for group in ordered_groups:
        latest = max(row["updated_dt"] for row in group)
        all_tags = set().union(*(row["tags"] for row in group))

        result.append({
            "first_name": pick(group, "first_name"),
            "last_name": pick(group, "last_name"),
            "zip": pick(group, "zip"),
            "email": pick(group, "email"),
            "phone": pick(group, "phone"),
            "source": pick(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(row["opted_out"] for row in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return result
